{
  "implementation": "def solve(case):
    payload = case['payload']
    threshold = payload['threshold']
    calls = payload['calls']
    accepted = []
    diagnostics = []
    for call in calls:
        gain = call['loss_without_call'] - call['loss_with_call']
        normalized_gain = gain / call['prediction_tokens']
        parseable = call['parseable']
        accept = parseable and (normalized_gain >= threshold)
        if accept:
            accepted.append(call['call_id'])
        diagnostics.append({
            'call_id': call['call_id'],
            'gain': round(gain, 6),
            'normalized_gain': round(normalized_gain, 6),
            'accepted': accept
        })
    return {
        'accepted': accepted,
        'diagnostics': diagnostics
    }"
}
